(root/'js/main.js').write_text('''"use strict";
const ARTICLES = '''+json.dumps([dict(title=t,topic=c,summary=d,author=a,date=date,featured=i==0) for i,(t,c,d,a,date,img) in enumerate(stories)])+''';
function findArticles(query, topic) { const q=query.trim().toLowerCase(); return ARTICLES.filter(a => (!topic || a.topic===topic) && (!q || [a.title,a.summary,a.topic,a.author].join(" ").toLowerCase().includes(q))); }
function newsletterError(email, choices) { if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/.test(email.trim())) return "Enter a valid email address, such as reader@example.com."; if (!choices.length) return "Choose at least one newsletter."; return ""; }
let previousFocus = null;
document.querySelectorAll("[data-open]").forEach(button => button.addEventListener("click", () => { previousFocus=button; const dialog=document.getElementById(button.dataset.open); dialog.showModal(); const field=dialog.querySelector("input,textarea"); if(field) field.focus(); }));
document.querySelectorAll("dialog").forEach(dialog => { dialog.querySelector("[data-close]").addEventListener("click",()=>dialog.close()); dialog.addEventListener("close",()=>{if(previousFocus) previousFocus.focus();}); });
const search=document.getElementById("search-form");
if(search){ const query=document.getElementById("query"), topic=document.getElementById("topic"), params=new URLSearchParams(location.search); query.value=params.get("q")||""; topic.value=["Democracy","Environment","Health","Education"].includes(params.get("topic"))?params.get("topic"):"";
 const render=()=>{ const list=findArticles(query.value,topic.value), box=document.getElementById("results"); box.replaceChildren(); document.getElementById("result-count").textContent=list.length+" sample result"+(list.length===1?"":"s")+" found."; if(!list.length){const p=document.createElement("p");p.textContent="No reporting matches your search. Try climate, records or clinic, or clear the filters.";box.append(p);} list.forEach(a=>{const article=document.createElement("article"); article.className="result";article.dataset.component="search-result";article.dataset.section="result-"+ARTICLES.indexOf(a);const topicLine=document.createElement("p");topicLine.className="eyebrow";topicLine.textContent=a.topic;const h=document.createElement("h3");if(a.featured){const link=document.createElement("a");link.href="article.html";link.textContent=a.title;h.append(link);}else{h.textContent=a.title;}const desc=document.createElement("p");desc.textContent=a.summary;const meta=document.createElement("p");meta.className="byline";meta.textContent="by "+a.author+" · "+a.date+(a.featured?"":" · Summary-only sample");article.append(topicLine,h,desc,meta);box.append(article);});}; search.addEventListener("submit",e=>{e.preventDefault();render();});render(); }
const newsletter=document.getElementById("newsletter-form");
if(newsletter) newsletter.addEventListener("submit",e=>{e.preventDefault();const email=document.getElementById("email"), choices=Array.from(newsletter.querySelectorAll("input[name=edition]:checked")).map(c=>c.value), message=document.getElementById("signup-message"), error=newsletterError(email.value,choices);message.className=error?"error":"success";email.removeAttribute("aria-invalid");if(error){message.textContent=error;if(error.startsWith("Enter")){email.setAttribute("aria-invalid","true");email.focus();}else{newsletter.querySelector("input[name=edition]").focus();}}else{message.textContent="Demo signup complete for "+choices.join(", ")+". No email was stored or sent, and no real subscription was created.";message.focus();}});
''')
